static Effect* CreateEffect(World& w, float x, float y, float z)
{
    Effect* e = &w.pool[w.created++];
    e->x = x; e->y = y; e->z = z; e->attached = false;
    return e;
}
static bool GetEffectFromString(const World& w, const char* name, long& type)
